    if (voice) utter.voice = voice;
    utter.onstart = () => {
      if (session === speakSession) updateUi(blockId, true);
    };
    utter.onend = () => speakNext();
    utter.onerror = () => {
      if (session === speakSession) updateUi(blockId, false);
    };
