function updateScheduleDetail() {
  const el = $("#fc-schedule-detail");
  if (!el) return;
  const sched = loadSchedule();
  const pool = flashQuestionPool();
  const now = Date.now();
  const day = 864e5;
  let due0 = 0;
  let due3 = 0;
  let later = 0;
  let none = 0;
  for (const q of pool) {
    const s = sched[q.id];
    if (!s || !s.due) {
      none += 1;
      continue;
    }
    if (s.due <= now) due0 += 1;
    else if (s.due <= now + 3 * day) due3 += 1;
    else later += 1;
  }
  el.textContent = `Programaci\xF3n (mazo filtrado): ${due0} vencidas o sin cita \xB7 ${due3} en las pr\xF3ximas 72 h \xB7 ${later} m\xE1s adelante \xB7 ${none} sin fecha de repaso guardada.`;
}
